class PricingService {
 public function __construct(private TenantContext $context,private FinancialActorService $actors,private StockService $stock){}
 private function owner(User $original):User{$actor=$this->actors->lock($original,'manage_products');if(!$actor->hasRole('owner'))throw new AuthorizationException;Business::whereKey($this->context->requireId())->lockForUpdate()->firstOrFail();return $actor;}
 public function preview(User $actor,array $input):array{return DB::transaction(function()use($actor,$input){$this->owner($actor);[$snapshot]=$this->configuration($input);return ['snapshot'=>$snapshot,'review_hash'=>SupervisorApprovalService::snapshotHash($snapshot)];});}
 public function save(User $original,array $input):array{return DB::transaction(function()use($original,$input){$actor=$this->owner($original);$key=strtolower($input['operation_id']);$fingerprint=SupervisorApprovalService::snapshotHash($input);$old=PricingOperation::where('operation_id',$key)->lockForUpdate()->first();if($old){$this->replay($actor,$old,$fingerprint);return ['rule'=>PricingRule::findOrFail($old->pricing_rule_id),'replayed'=>true];}[$snapshot,$targets]=$this->configuration($input);if(!hash_equals(SupervisorApprovalService::snapshotHash($snapshot),$input['review_hash']??''))throw new ApiException('PRICING_REVIEW_CHANGED','Review the pricing rule again before saving.',409);$rule=PricingRule::create([...array_diff_key($snapshot,array_flip(['operation_id','targets','max_qty'])),'user_id'=>$actor->id]);foreach($targets as$target)PricingTarget::create(['pricing_rule_id'=>$rule->id,...$target]);PricingOperation::create(['pricing_rule_id'=>$rule->id,'user_id'=>$actor->id,'device_id'=>$actor->currentAccessToken()->device_id,'operation_id'=>$key,'request_fingerprint'=>$fingerprint,'action'=>'create']);activity('pricing')->performedOn($rule)->causedBy($actor)->event('pricing_rule_created')->withProperties(['attributes'=>['rule_id'=>$rule->publicId(),'kind'=>$rule->kind,'starts_at'=>$rule->starts_at->toIso8601String()]])->log('Owner configured pricing');return ['rule'=>$rule,'replayed'=>false];},3);}
 public function cancelPreview(User $actor,PricingRule $rule,array $input):array{return DB::transaction(function()use($actor,$rule,$input){$this->owner($actor);$rule->refreshForUpdate();$snapshot=$this->cancelSnapshot($rule,$input);return ['snapshot'=>$snapshot,'review_hash'=>SupervisorApprovalService::snapshotHash($snapshot)];});}
 public function cancel(User $original,PricingRule $rule,array $input):array{return DB::transaction(function()use($original,$rule,$input){$actor=$this->owner($original);$rule->refreshForUpdate();$fingerprint=SupervisorApprovalService::snapshotHash(['rule_id'=>$rule->publicId(),...$input]);$old=PricingOperation::where('operation_id',strtolower($input['operation_id']))->lockForUpdate()->first();if($old){$this->replay($actor,$old,$fingerprint);return ['rule'=>$rule,'replayed'=>true];}$snapshot=$this->cancelSnapshot($rule,$input);if(!hash_equals(SupervisorApprovalService::snapshotHash($snapshot),$input['review_hash']??''))throw new ApiException('PRICING_REVIEW_CHANGED','Review the cancellation again.',409);if($rule->cancelled_at)throw new ApiException('PRICING_CANCELLED','This rule has already been cancelled.',409);$rule->cancelled_at=now();$rule->save();$this->recordEffectiveSchedules();PricingOperation::create(['pricing_rule_id'=>$rule->id,'user_id'=>$actor->id,'device_id'=>$actor->currentAccessToken()->device_id,'operation_id'=>strtolower($input['operation_id']),'request_fingerprint'=>$fingerprint,'action'=>'cancel']);activity('pricing')->performedOn($rule)->causedBy($actor)->event('pricing_rule_cancelled')->withProperties(['attributes'=>['rule_id'=>$rule->publicId(),'reason'=>trim($input['reason'])]])->log('Owner cancelled pricing');return ['rule'=>$rule,'replayed'=>false];},3);}
 private function replay(User $actor,PricingOperation $old,string $fingerprint):void{if($old->user_id!==$actor->id||$old->device_id!==$actor->currentAccessToken()->device_id||!hash_equals($old->request_fingerprint,$fingerprint))throw new ApiException('OPERATION_ID_REUSED','This pricing reference belongs to other details or staff.',409);}
 private function cancelSnapshot(PricingRule $rule,array $input):array{return ['operation_id'=>strtolower($input['operation_id']),'rule_id'=>$rule->publicId(),'cancelled_at'=>$rule->cancelled_at?->toIso8601String(),'reason'=>trim($input['reason'])];}
 private function configuration(array $input):array{try{return $this->configurationUnchecked($input);}catch(\InvalidArgumentException|\OverflowException $e){throw new ApiException('VALIDATION_ERROR',$e->getMessage(),422);}}
 private function configurationUnchecked(array $input):array{
  $kind=$input['kind'];$start=CarbonImmutable::createFromFormat('!Y-m-d\TH:i',$input['starts_at'],'Africa/Dar_es_Salaam')->utc();$end=isset($input['ends_at'])?CarbonImmutable::createFromFormat('!Y-m-d\TH:i',$input['ends_at'],'Africa/Dar_es_Salaam')->utc():null;
  if(($kind!=='schedule'&&!$end)||($end&&$end<=$start))throw new ApiException('VALIDATION_ERROR','Offers need an end after their start, in Tanzania time.',422,'ends_at');
  $price=$input['price']??null;$bps=$input['basis_points']??null;$buy=$input['buy_qty']??null;$free=$input['free_qty']??null;
  if(in_array($kind,['schedule','fixed_price'])&&(!is_int($price)||$bps!==null||$buy!==null||$free!==null))throw new ApiException('VALIDATION_ERROR','This kind requires only a fixed integer price.',422);
  if($kind==='percentage'&&($bps===null||$price!==null||$buy!==null||$free!==null))throw new ApiException('VALIDATION_ERROR','Percentage offers require basis points only.',422);
  if($kind==='buy_get'&&($buy===null||$free===null||$price!==null||$bps!==null))throw new ApiException('VALIDATION_ERROR','Buy/get offers require positive buy and free quantities only.',422);
  if($kind==='markdown'&&(($price===null)==($bps===null)||$buy!==null||$free!==null||count($input['targets'])!==1))throw new ApiException('VALIDATION_ERROR','A markdown needs one batch and either a price or basis points.',422);
  $targets=[];$public=[];$seen=[];$cap=null;
  foreach($input['targets']as$target){$p=(new Product)->resolveRouteBindingQuery(Product::query(),$target['product_id'])->lockForUpdate()->firstOrFail();if(!$p->is_active)throw new ApiException('PRODUCT_INACTIVE','Activate the product before configuring prices.',409);$pack=isset($target['packaging_id'])?(new ProductPackaging)->resolveRouteBindingQuery(ProductPackaging::where('product_id',$p->id),$target['packaging_id'])->lockForUpdate()->firstOrFail():null;if($pack&&($pack->archived_at||!$pack->is_active))throw new ApiException('PACKAGING_VERSION_CHANGED','Select the current active packaging version.',409);if($kind==='buy_get'&&$p->quantity_type==='weight'&&!$pack)throw new ApiException('VALIDATION_ERROR','Buy/get applies to whole counted items or whole packs, not loose weighed goods.',422);$batch=null;if($kind==='markdown'){if(!isset($target['batch_id'])||!isset($input['max_qty']))throw new ApiException('VALIDATION_ERROR','Choose the batch and maximum base quantity for this markdown.',422);$batch=(new ProductBatch)->resolveRouteBindingQuery($this->stock->eligibleBatches(ProductBatch::where('product_id',$p->id)),$target['batch_id'])->lockForUpdate()->firstOrFail();$cap=Quantity::parse($input['max_qty'],$p->quantity_type==='weight');if($cap<1||$cap>$batch->qty_remaining_atoms)throw new ApiException('VALIDATION_ERROR','The markdown quantity must fit eligible stock in the selected batch.',422);}elseif(isset($target['batch_id'])||isset($input['max_qty']))throw new ApiException('VALIDATION_ERROR','Batch limits belong to markdowns only.',422);
   $identity=$p->publicId().'|'.($pack?->publicId()??'');if(isset($seen[$identity]))throw new ApiException('VALIDATION_ERROR','Do not repeat a product/pack target.',422);$seen[$identity]=true;
   if($kind==='schedule'){ $overlap=PricingRule::where('kind','schedule')->whereNull('cancelled_at')->whereIn('id',PricingTarget::where('product_id',$p->id)->where('packaging_id',$pack?->id)->orderBy('pricing_rule_id')->lockForUpdate()->get(['pricing_rule_id'])->pluck('pricing_rule_id'))->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>',$start));if($end)$overlap->where('starts_at','<',$end);if($overlap->lockForUpdate()->first())throw new ApiException('PRICING_OVERLAP','This product/pack already has a price schedule in that window. Cancel or use a non-overlapping window.',409); }
   $targets[]=['product_id'=>$p->id,'packaging_id'=>$pack?->id,'batch_id'=>$batch?->id];$public[]=['product_id'=>$p->publicId(),'product_name'=>$p->name,'packaging_id'=>$pack?->publicId(),'packaging_name'=>$pack?->name,'packaging_version'=>$pack?->version,'batch_id'=>$batch?->publicId(),'batch_number'=>$batch?->batch_number,'unit'=>$p->unit];
  }
  return [['operation_id'=>strtolower($input['operation_id']),'name'=>trim($input['name']),'kind'=>$kind,'priority'=>$input['priority'],'reason'=>trim($input['reason']),'price'=>$price,'basis_points'=>$bps,'buy_qty'=>$buy,'free_qty'=>$free,'max_atoms'=>$cap,'starts_at'=>$start->format('Y-m-d H:i:s'),'ends_at'=>$end?->format('Y-m-d H:i:s'),'targets'=>$public],$targets];
 }
 public function recordEffectiveSchedules():int {
  return DB::transaction(function(){Business::whereKey($this->context->requireId())->lockForUpdate()->firstOrFail();$count=0;$rules=PricingRule::where('kind','schedule')->where('starts_at','<=',now())->orderBy('starts_at')->orderBy('id')->lockForUpdate()->get();
   foreach($rules as$r){$start=$r->starts_at->greaterThan($r->created_at)?$r->starts_at:$r->created_at;$finish=$r->cancelled_at&&(!$r->ends_at||$r->cancelled_at<$r->ends_at)?$r->cancelled_at:$r->ends_at;if($finish&&$finish<$start)continue;$actor=User::findOrFail($r->user_id);
    foreach($r->targets()->lockForUpdate()->get()as$t){if($finish&&$finish->equalTo($start)&&!$t->activated_at)continue;$product=Product::withTrashed()->whereKey($t->product_id)->lockForUpdate()->firstOrFail();$pack=$t->packaging_id?ProductPackaging::whereKey($t->packaging_id)->lockForUpdate()->firstOrFail():null;
     if(!$t->activated_at){$old=$this->historicalPrice($product,$pack,$start->copy()->subSecond(),$r->id);$priced=clone $product;$pricedPack=$pack?clone $pack:null;if($pricedPack)$pricedPack->selling_price=$r->price;else$priced->selling_price=$r->price;app(ProductPriceHistoryService::class)->record($actor,$priced,$old,$pricedPack,$start,$r->publicId());$t->activated_at=now();$t->save();$count++;}
     if($finish&&$finish<=now()&&!$t->finished_at){$next=$this->historicalPrice($product,$pack,$finish,$r->id);$priced=clone $product;$pricedPack=$pack?clone $pack:null;if($pricedPack)$pricedPack->selling_price=$next;else$priced->selling_price=$next;app(ProductPriceHistoryService::class)->record($actor,$priced,$r->price,$pricedPack,$finish,$r->publicId());$t->finished_at=now();$t->save();$count++;}
    }
   }return $count;
  },3);
 }
 private function historicalPrice(Product $product,?ProductPackaging $pack,$at,int $excluded):int {
  $other=PricingRule::where('kind','schedule')->where('id','!=',$excluded)->where('created_at','<=',$at)->where('starts_at','<=',$at)->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>',$at))->where(fn($q)=>$q->whereNull('cancelled_at')->orWhere('cancelled_at','>',$at))->whereIn('id',PricingTarget::where('product_id',$product->id)->where('packaging_id',$pack?->id)->orderBy('pricing_rule_id')->lockForUpdate()->get(['pricing_rule_id'])->pluck('pricing_rule_id'))->orderBy('priority')->orderBy('public_id')->lockForUpdate()->first();if($other)return $other->price;
  $history=ProductPriceHistory::where('product_id',$product->id)->where('packaging_id',$pack?->id)->where('source','catalogue')->where('created_at','<=',$at)->orderByDesc('created_at')->orderByDesc('id')->lockForUpdate()->first();return $history?->new_price??($pack?->selling_price??$product->selling_price);
 }
 public function activeRules(){
  $query=PricingRule::whereNull('cancelled_at')->where('starts_at','<=',now())->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>',now()))->orderBy('priority')->orderBy('public_id');
  if(DB::transactionLevel()>0)$query->lockForUpdate()->with(['targets'=>fn($q)=>$q->lockForUpdate()->with(['product'=>fn($p)=>$p->lockForUpdate(),'packaging'=>fn($p)=>$p->lockForUpdate(),'batch'=>fn($p)=>$p->lockForUpdate()])]);else$query->with(['targets.product','targets.packaging','targets.batch']);
  return $query->get();
 }
 private function consumedAtoms(int $ruleId):int{$query=PricingConsumption::where('pricing_rule_id',$ruleId);if(DB::transactionLevel()<1)return Quantity::parse((string)$query->sum('qty_atoms'));$total=0;foreach($query->orderBy('id')->lockForUpdate()->get(['qty_atoms'])as$row)$total=ExactMath::add($total,$row->qty_atoms);return $total;}
 private function matches(PricingRule $rule,array $line):bool{foreach($rule->targets as$t)if($t->product?->publicId()===$line['product_id']&&($t->packaging?->publicId()??null)===($line['packaging_id']??null))return true;return false;}
 public function effectivePrice(Product $product,?ProductPackaging $pack=null):int{$line=['product_id'=>$product->publicId(),'packaging_id'=>$pack?->publicId()];foreach($this->activeRules()as$r)if($r->kind==='schedule'&&$this->matches($r,$line))return $r->price;return $pack?->selling_price??$product->selling_price;}
 /** Caller holds fresh actor/business/product locks. Inputs are canonical Laravel sale lines. */
 public function apply(User $actor,array $lines,?string $branchId=null,bool $includeConditional=true):array{
  $actor->assertCurrentBusiness();if(DB::transactionLevel()<1)throw new \LogicException('Pricing requires the sale transaction.');$this->recordEffectiveSchedules();$rules=$this->activeRules();if($rules->isEmpty())return $lines;
  foreach($lines as&$line){foreach($rules as$r)if($r->kind==='schedule'&&$this->matches($r,$line)){$line['catalogue_unit_price']=$line['unit_price'];$line['unit_price']=$r->price;$line['price_schedule_id']=$r->publicId();break;}$line['line_total']=Money::lineTotal(Quantity::parse($line['qty'],$line['quantity_type']==='weight'&&!$line['packaging_id']),$line['unit_price'],$line['quantity_type']==='weight'&&!$line['packaging_id']);}unset($line);if(!$includeConditional)return $lines;
  $free=[];foreach($rules as$r){if($r->kind!=='buy_get')continue;$eligible=[];$count=0;foreach($lines as$i=>$line)if($this->matches($r,$line)&&!($line['quantity_type']==='weight'&&!$line['packaging_id'])){$units=Quantity::parse($line['qty']);$count=ExactMath::add($count,$units);$eligible[]=['index'=>$i,'units'=>$units,'price'=>$line['unit_price']];}usort($eligible,fn($a,$b)=>[$a['price'],$a['index']]<=>[$b['price'],$b['index']]);$left=ExactMath::multiply(intdiv($count,$r->buy_qty+$r->free_qty),$r->free_qty);foreach($eligible as$entry){$take=min($left,$entry['units']);$free[$r->id][$entry['index']]=Money::lineTotal($take,$entry['price']);$left-=$take;}}
  $used=[];$caps=[];foreach($rules as$r)if($r->kind==='markdown'){$sum=$this->consumedAtoms($r->id);$caps[$r->id]=max(0,$r->max_atoms-$sum);}
  foreach($lines as$i=>&$line){$gross=$line['line_total'];$best=['net'=>$gross,'rule'=>null,'price'=>$line['unit_price']];foreach($rules as$r){if(!$this->matches($r,$line)||in_array($r->kind,['schedule','markdown']))continue;$price=$r->kind==='fixed_price'?$r->price:($r->kind==='percentage'?Money::amount(ExactMath::roundProductRatio($line['unit_price'],10000-$r->basis_points,10000)):$line['unit_price']);$net=$r->kind==='buy_get'?$gross-($free[$r->id][$i]??0):($r->kind==='percentage'?PricingMath::percentageNet($gross,$r->basis_points):Money::lineTotal(Quantity::parse($line['qty'],$line['quantity_type']==='weight'&&!$line['packaging_id']),$price,$line['quantity_type']==='weight'&&!$line['packaging_id']));if($net<$best['net'])$best=['net'=>$net,'rule'=>$r,'price'=>$price];}
   $product=(new Product)->resolveRouteBinding($line['product_id']);$atoms=Quantity::parse($line['base_qty'],$line['quantity_type']==='weight');$left=$atoms;$segments=[];$batches=$this->stock->eligibleBatches(ProductBatch::where('product_id',$product->id))->orderByRaw('expiry_date IS NULL')->orderBy('expiry_date')->orderByRaw('CASE WHEN expiry_date IS NULL THEN received_at ELSE NULL END')->orderBy('id')->lockForUpdate()->get();
   foreach($batches as$b){$take=min($left,max(0,$b->qty_remaining_atoms-($used[$b->id]??0)));if(!$take)continue;$used[$b->id]=ExactMath::add($used[$b->id]??0,$take);$left-=$take;$split=[$take];foreach($rules as$r)if($r->kind==='markdown'&&$this->matches($r,$line)&&$r->targets->first()->batch_id===$b->id&&($caps[$r->id]??0)>0&&$caps[$r->id]<$take)$split[]=$caps[$r->id];$cuts=array_unique($split);sort($cuts);$previous=0;foreach($cuts as$cut){$segments[]=['batch'=>$b,'atoms'=>$cut-$previous];$previous=$cut;}if(!$left)break;}
   if($left)throw new ApiException('INSUFFICIENT_STOCK','Not enough eligible stock for '.$product->name.'.',400,'items');
   $alloc=[];$position=0;$prevGross=0;$prevNet=0;$automatic=0;$offers=[];$markdownProgress=[];
   foreach($segments as$segment){$position=ExactMath::add($position,$segment['atoms']);$toGross=ExactMath::roundProportion($gross,$position,$atoms);$toNet=ExactMath::roundProportion($best['net'],$position,$atoms);$partGross=$toGross-$prevGross;$partNet=$toNet-$prevNet;$prevGross=$toGross;$prevNet=$toNet;$winner=$best['rule'];$effective=$best['price'];
    foreach($rules as$r){if($r->kind!=='markdown'||!$this->matches($r,$line)||$r->targets->first()->batch_id!==$segment['batch']->id||($caps[$r->id]??0)<$segment['atoms'])continue;$price=$r->price??Money::amount(ExactMath::roundProductRatio($line['unit_price'],10000-$r->basis_points,10000));$divisor=$line['packaging_id']?(int)$line['conversion_atoms']:($line['quantity_type']==='weight'?1000:1);$progress=$markdownProgress[$r->id]??['atoms'=>0,'gross'=>0,'net'=>0];$progress['atoms']=ExactMath::add($progress['atoms'],$segment['atoms']);$progress['gross']=ExactMath::add($progress['gross'],$partGross);$cumulativeNet=$r->basis_points!==null?PricingMath::percentageNet($progress['gross'],$r->basis_points):Money::amount(PricingMath::roundScaledProduct($progress['atoms'],$price,$divisor));$net=min($partGross,max(0,$cumulativeNet-$progress['net']));$progress['net']=$cumulativeNet;$markdownProgress[$r->id]=$progress;if($net<$partNet||($net===$partNet&&$winner&&[$r->priority,$r->public_id]<[$winner->priority,$winner->public_id])){$partNet=$net;$winner=$r;$effective=$price;}}
    $discount=$partGross-$partNet;if($discount>0&&$winner){$offers[$winner->publicId()]=['id'=>$winner->publicId(),'name'=>$winner->name,'kind'=>$winner->kind,'priority'=>$winner->priority];if($winner->kind==='markdown')$caps[$winner->id]-=$segment['atoms'];}else$winner=null;$automatic=Money::amount(ExactMath::add($automatic,$discount));
    $alloc[]=['batch_id'=>$segment['batch']->publicId(),'base_qty'=>Quantity::format($segment['atoms'],$line['quantity_type']==='weight'),'qty_atoms'=>(string)$segment['atoms'],'gross_total'=>$partGross,'net_total'=>$partNet,'effective_unit_price'=>$effective,'automatic_discount'=>$discount,'offer_id'=>$winner?->publicId(),'offer_kind'=>$winner?->kind];
   }
   $line['automatic_discount']=$automatic;$line['automatic_offers']=array_values($offers);$line['pricing_allocations']=$alloc;
  }unset($line);return $lines;
 }
 public function consume(User $actor,Sale $sale,array $lines):void{$actor->assertCurrentBusiness();$sale->assertCurrentBusiness();if(DB::transactionLevel()<1)throw new \LogicException('Pricing consumption must commit with the sale.');$totals=[];foreach($lines as$line)foreach($line['pricing_allocations']??[]as$a)if(($a['offer_kind']??null)==='markdown'&&$a['offer_id'])$totals[$a['offer_id']]=ExactMath::add($totals[$a['offer_id']]??0,Quantity::parse($a['base_qty'],$line['quantity_type']==='weight'));foreach($totals as$id=>$atoms){$r=(new PricingRule)->resolveRouteBindingQuery(PricingRule::query(),$id)->lockForUpdate()->firstOrFail();if($r->cancelled_at||$r->starts_at->isFuture()||($r->ends_at&&$r->ends_at<=now()))throw new ApiException('SALE_CHANGED','The markdown window changed. Review the sale again.',409);$used=$this->consumedAtoms($r->id);if(ExactMath::add($used,$atoms)>$r->max_atoms)throw new ApiException('SALE_CHANGED','The markdown quantity has been used. Review the sale again.',409);PricingConsumption::create(['pricing_rule_id'=>$r->id,'sale_id'=>$sale->id,'qty_atoms'=>$atoms]);}}
}
